// Writes the built standalone IIFE bundle into the firmware's generated header.
// Run automatically at the end of `npm run build` in "Home Assistant Card".
// The output header is GENERATED — do not hand-edit smartmouse_bundle.h.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..');
const bundlePath = join(repoRoot, 'Home Assistant Card', 'dist', 'smartmouse-standalone.js');
const outPath = join(repoRoot, 'Arduino IDE', 'SmartMouse', 'smartmouse_bundle.h');

const js = readFileSync(bundlePath, 'utf8');

// Raw string delimiter unlikely to appear in minified JS.
if (js.includes(')SMJS"')) {
  throw new Error('Bundle contains the raw-string delimiter )SMJS" — pick a different delimiter.');
}

const header = `// AUTO-GENERATED by scripts/embed-bundle.mjs — DO NOT EDIT.
// Built from "Home Assistant Card/standalone/*.ts" (shared gesture/sensor logic).
// Served by the firmware at GET /smartmouse.js.
#ifndef SMARTMOUSE_BUNDLE_H
#define SMARTMOUSE_BUNDLE_H

const char SMARTMOUSE_BUNDLE_JS[] PROGMEM = R"SMJS(
${js})SMJS";

#endif
`;

writeFileSync(outPath, header);
console.log(`embed-bundle: wrote ${outPath} (${js.length} bytes of JS)`);
